//! Golden fiscal-calendar vectors through 2100 (plan §7.2 "golden vectors
//! through 2100, including 53-week years and leap days"; fa-94qd item 4).
//!
//! Each file under `tests/golden/` lists every period of fiscal years
//! 1990..=2100 of one calendar, one line each: `code kind start end` (end
//! exclusive). The files were generated by an implementation independent of
//! fa-time (Python's `datetime` for every civil-date step, from the
//! calendar rules of plan §7.2), so a mismatch is a disagreement between two
//! implementations, never a snapshot of this one: regenerate a file only
//! from that independent generator, after finding which side is wrong.

#![forbid(unsafe_code)]

use fa_time::{FiscalCalendar, WeekPattern, Weekday, YearEndRule};

/// The calendars the golden files cover, by file name.
fn calendars() -> Vec<(&'static str, FiscalCalendar, &'static str)> {
    use Weekday::{Friday, Saturday, Sunday};
    use YearEndRule::{LastWeekdayOfMonth, WeekdayNearestEnd};
    vec![
        (
            "monthly_jan_adj1",
            FiscalCalendar::monthly("golden", 1, 1).unwrap(),
            include_str!("golden/monthly_jan_adj1.txt"),
        ),
        (
            "monthly_jul_adj0",
            FiscalCalendar::monthly("golden", 7, 0).unwrap(),
            include_str!("golden/monthly_jul_adj0.txt"),
        ),
        (
            "w445_nearest_saturday_dec_adj1",
            FiscalCalendar::weeks(
                "golden",
                WeekPattern::W445,
                WeekdayNearestEnd {
                    weekday: Saturday,
                    month: 12,
                },
                1,
            )
            .unwrap(),
            include_str!("golden/w445_nearest_saturday_dec_adj1.txt"),
        ),
        (
            "w454_last_saturday_jan_adj0",
            FiscalCalendar::weeks(
                "golden",
                WeekPattern::W454,
                LastWeekdayOfMonth {
                    weekday: Saturday,
                    month: 1,
                },
                0,
            )
            .unwrap(),
            include_str!("golden/w454_last_saturday_jan_adj0.txt"),
        ),
        (
            "w544_nearest_sunday_sep_adj2",
            FiscalCalendar::weeks(
                "golden",
                WeekPattern::W544,
                WeekdayNearestEnd {
                    weekday: Sunday,
                    month: 9,
                },
                2,
            )
            .unwrap(),
            include_str!("golden/w544_nearest_sunday_sep_adj2.txt"),
        ),
        (
            "w5253_last_friday_dec_adj1",
            FiscalCalendar::week_52_53(
                "golden",
                LastWeekdayOfMonth {
                    weekday: Friday,
                    month: 12,
                },
                1,
            )
            .unwrap(),
            include_str!("golden/w5253_last_friday_dec_adj1.txt"),
        ),
    ]
}

/// fa-time's own lines for `calendar`, in the golden format.
fn generated(calendar: &FiscalCalendar) -> Vec<String> {
    let mut lines = Vec::new();
    for fy in 1990..=2100 {
        for p in calendar.periods_for_year(fy).expect("a generated year") {
            lines.push(format!(
                "{} {:?} {} {}",
                p.code,
                p.kind,
                p.start.render(),
                p.end.render()
            ));
        }
    }
    lines
}

/// `Err` names the first period where `golden` and `lines` differ.
fn compare(name: &str, golden: &str, lines: &[String]) -> Result<(), String> {
    let expected: Vec<&str> = golden
        .lines()
        .filter(|line| !line.starts_with('#') && !line.is_empty())
        .collect();
    for (i, (want, got)) in expected.iter().zip(lines).enumerate() {
        if *want != got.as_str() {
            return Err(format!(
                "{name}: period line {} differs\n  golden:  {want}\n  fa-time: {got}",
                i + 1
            ));
        }
    }
    if expected.len() != lines.len() {
        return Err(format!(
            "{name}: golden has {} periods, fa-time generates {}",
            expected.len(),
            lines.len()
        ));
    }
    Ok(())
}

#[test]
fn periods_match_golden_files_through_2100() {
    for (name, calendar, golden) in calendars() {
        compare(name, golden, &generated(&calendar)).unwrap_or_else(|e| panic!("{e}"));
    }
    // The files hold what the plan names. A 53-week year: retail FY2025
    // (nearest Saturday to December 31) gives its twelfth period six weeks,
    // as the CLI's retail-calendar test also pins. Leap days: a five-week
    // period across 29 February 2024 still spans exactly 35 days, and one
    // across February 2100 (not a leap year: the century rule) does too.
    let all: Vec<&str> = calendars().into_iter().map(|(_, _, g)| g).collect();
    assert!(all[2].contains("FY2025-P12 Normal 2025-11-23 2026-01-04"));
    assert!(all[2].contains("FY2024-P03 Normal 2024-02-25 2024-03-31"));
    assert!(all[2].contains("FY2100-P03 Normal 2100-02-28 2100-04-04"));
}

/// Planted: one edited character in a golden file fails, naming the line.
#[test]
fn an_edited_golden_file_fails_naming_its_line() {
    let (name, calendar, golden) = calendars().remove(0);
    let edited = golden.replacen(
        "FY2000-P02 Normal 2000-02-01",
        "FY2000-P02 Normal 2000-02-02",
        1,
    );
    assert_ne!(edited, golden, "the planted edit applies");
    let err = compare(name, &edited, &generated(&calendar)).expect_err("the edit is caught");
    assert!(err.contains("FY2000-P02"), "{err}");
    let truncated: String = golden.lines().take(40).map(|l| format!("{l}\n")).collect();
    assert!(compare(name, &truncated, &generated(&calendar)).is_err());
}
